import{_ as e,o as a,c as i,a2 as d}from"./chunks/framework.XXezeKOl.js";const c=JSON.parse('{"title":"实战项目总览","description":"10 个由浅入深的 Agent 实战项目，从命令行聊天到企业知识助手，每个项目都给出 Python / Go / Java 代码。","frontmatter":{"title":"实战项目总览","description":"10 个由浅入深的 Agent 实战项目，从命令行聊天到企业知识助手，每个项目都给出 Python / Go / Java 代码。"},"headers":[],"relativePath":"projects/index.md","filePath":"projects/index.md","lastUpdated":null}'),s={name:"projects/index.md"};function r(n,t,o,p,h,l){return a(),i("div",null,[...t[0]||(t[0]=[d(`<h1 id="实战项目总览" tabindex="-1">实战项目总览 <a class="header-anchor" href="#实战项目总览" aria-label="Permalink to &quot;实战项目总览&quot;">​</a></h1><p>光看原理学不会 Agent 开发。这里的 10 个项目按难度递进，每个项目都对应教程里的若干模块：先读模块里的原理，再动手做项目，把知识点串成能跑的程序。</p><p>每个项目都包含需求说明、架构图、分步实现、运行与测试、扩展挑战。代码全部内联在页面里，复制即可运行。Python 是主语言；01-04 和 08 同时给出完整的 Go 与 Java 版本，其余项目给出核心部分的 Go / Java 实现。</p><div class="tip custom-block"><p class="custom-block-title">开始之前</p><p>所有项目统一使用 OpenAI 兼容的 Chat Completions API，通过环境变量切换厂商（OpenAI、DeepSeek、通义千问、Kimi 等）：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPENAI_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你的 Key&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPENAI_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://api.openai.com/v1&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 可选，换成其他厂商的兼容地址</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LLM_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gpt-4o-mini&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                        # 示例，按你的厂商填写</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Key 只放在环境变量或 <code>.env</code> 中，不要写进代码，也不要提交到 Git。</p></div><h2 id="项目列表" tabindex="-1">项目列表 <a class="header-anchor" href="#项目列表" aria-label="Permalink to &quot;项目列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>难度</th><th>预计时间</th><th>涉及模块</th><th>技能点</th></tr></thead><tbody><tr><td><a href="/projects/01-cli-chat">01 命令行聊天助手</a></td><td>★</td><td>30 分钟</td><td><a href="/guide/03-llm-api/first-call">03 大模型 API</a></td><td>第一次调用、多轮历史、流式输出</td></tr><tr><td><a href="/projects/02-tool-agent">02 天气日程工具 Agent</a></td><td>★★</td><td>1～1.5 小时</td><td><a href="/guide/05-tool-calling/concept">05 Tool Calling</a></td><td>JSON Schema 描述工具、工具循环、错误回传</td></tr><tr><td><a href="/projects/03-react-agent">03 手写 ReAct Agent</a></td><td>★★</td><td>1.5 小时</td><td><a href="/guide/06-agent-loop/react">06 Agent 循环</a></td><td>Thought / Action / Observation、步数上限、轨迹打印</td></tr><tr><td><a href="/projects/04-pdf-rag">04 个人 PDF 知识库</a></td><td>★★★</td><td>2～3 小时</td><td><a href="/guide/09-rag/overview">09 RAG 知识库</a>、<a href="/guide/02-llm-basics/embeddings">Embedding</a></td><td>PDF 解析、切分、向量检索、带引用回答</td></tr><tr><td><a href="/projects/05-mcp-server">05 开发自己的 MCP Server</a></td><td>★★★</td><td>1.5～2 小时</td><td><a href="/guide/10-mcp/mcp-server">10 MCP 与 A2A</a></td><td>FastMCP、Tool 与 Resource、接入 Claude Desktop</td></tr><tr><td><a href="/projects/06-research-agent">06 网页研究员 Agent</a></td><td>★★★</td><td>2～3 小时</td><td><a href="/guide/06-agent-loop/plan-execute">06 Agent 循环</a>、<a href="/guide/07-context-engineering/compression">07 上下文工程</a>、<a href="/guide/15-production/prompt-injection">Prompt 注入</a></td><td>可插拔搜索、礼貌抓取、防 SSRF、引用报告</td></tr><tr><td><a href="/projects/07-writing-team">07 多 Agent 写作团队</a></td><td>★★★</td><td>2～3 小时</td><td><a href="/guide/12-multi-agent/patterns">12 多 Agent 系统</a>、<a href="/guide/11-frameworks/langgraph">LangGraph</a></td><td>角色拆分、结构化输出驱动分支、修订上限</td></tr><tr><td><a href="/projects/08-code-review">08 代码审查 Agent</a></td><td>★★★</td><td>2～3 小时</td><td><a href="/guide/13-coding-agent/coding-agents">13 Coding 与 Computer-Use</a>、<a href="/guide/04-prompt/structured-output">结构化输出</a></td><td>安全调用 git、结构化审查结果、接入 CI</td></tr><tr><td><a href="/projects/09-agent-workbench">09 全栈 Agent 工作台</a></td><td>★★★★</td><td>4～6 小时</td><td><a href="/guide/01-programming/streaming-sse">流式输出与 SSE</a>、<a href="/guide/15-production/serving">15 安全与生产化</a></td><td>FastAPI + SSE、Vue 3 聊天界面、鉴权与 CORS</td></tr><tr><td><a href="/projects/10-enterprise-assistant">10 毕业项目：企业知识助手</a></td><td>★★★★★</td><td>20～30 小时</td><td><a href="/guide/08-memory/long-term">08 记忆系统</a>、<a href="/guide/14-evaluation/observability">14 评估与可观测性</a>、<a href="/guide/15-production/guardrails">15 安全与生产化</a></td><td>RAG + 工具 + 记忆、评估、追踪、护栏、Docker 部署</td></tr></tbody></table><h2 id="推荐顺序" tabindex="-1">推荐顺序 <a class="header-anchor" href="#推荐顺序" aria-label="Permalink to &quot;推荐顺序&quot;">​</a></h2><ul><li>入门（01 → 02 → 03）：从第一次调用 API 到亲手写出 Agent 循环。01 只要 30 分钟，02 做完你就有了一个能调用工具的 Agent。</li><li>核心能力（04 → 05 → 06）：分别对应知识检索、工具生态和联网研究，三者之间相对独立，可以按兴趣调整顺序。</li><li>工程进阶（07 → 08 → 09）：多 Agent 协作、结构化输出接入工程流程，以及把 Agent 做成带界面的 Web 服务。</li><li>毕业（10）：把前面所有能力组合成一个可交付、可评估、可部署的系统。建议至少完成 02、04、09 后再开始。</li></ul><p>如果你还没决定从哪里学起，可以先看 <a href="/roadmap/">学习路线</a>，按自己的背景选一条路径，再回到这里挑项目。</p>`,9)])])}const u=e(s,[["render",r]]);export{c as __pageData,u as default};
